def create_file_chunk(
    self,
    relative: str,
    content: str,
    mode: str,
) -> str | None:
    target = self.resolve(relative)
    if target.exists():
        raise HelixError(
            f"Refusing to overwrite existing file {relative}; use Patch Forge for modifications."
        )

    staging_root = (self.root / ".helix" / "staging").resolve()
    staging_root.mkdir(parents=True, exist_ok=True)
    stage = (staging_root / f"{relative}.part").resolve()

    try:
        stage.relative_to(staging_root)
    except ValueError as exc:
        raise HelixError(f"Invalid staged file path: {relative}") from exc

    mode = mode.lower().strip()

    if mode == "start":
        stage.parent.mkdir(parents=True, exist_ok=True)
        stage.write_text(content, encoding="utf-8", newline="\n")
        return None

    if mode not in {"append", "finish"}:
        raise HelixError(
            "create_file_chunk mode must be start, append, or finish."
        )

    if not stage.is_file():
        raise HelixError(
            f"No staged file exists for {relative}; begin with mode=start."
        )

    with stage.open("a", encoding="utf-8", newline="\n") as handle:
        handle.write(content)

    if mode == "append":
        return None

    target.parent.mkdir(parents=True, exist_ok=True)
    stage.replace(target)
    return hashlib.sha256(target.read_bytes()).hexdigest()

